// Fixture identity constants (no-coincidence discipline: independent of the
// other qa fixtures' titles and ids) and the convention values the stub
// serves — every served-block assertion re-derives its want from these.
const (
	qaMediaDir     = "QA Media Vault S01"
	qaMediaEp1Rel  = qaMediaDir + "/QA Media Vault S01E01.mkv"
	qaMediaEp2Rel  = qaMediaDir + "/QA Media Vault S01E02.mkv"
	qaMediaTitle   = "QA Media Vault"
	qaMediaRussian = "Ку Медиа Вольт"
	qaMediaID      = 9901 // the selected anime (candidate 0 beats the movie decoy)
	qaMediaDecoyID = 9902 // the movie decoy the preference score must not pick
	qaMediaPlugin  = "shikimori"
	qaMediaDesc    = "qa media vault: описание тайтла"
	qaMediaAired   = "2019-10-02"
	qaMediaScore   = 7.7 // upstream ships "7.7" (a decimal STRING); Convert decodes to a number
)

// qaMediaWriteFixtures writes the serial library root: one series directory,
// two episode files (E01 stays the untouched REAL row; E02 becomes the
// episode fixture's host row).
func qaMediaWriteFixtures(t *testing.T, root string) {
	t.Helper()
	qaSerialMedia(t, filepath.Join(root, qaMediaEp1Rel))
	qaSerialMedia(t, filepath.Join(root, qaMediaEp2Rel))
}

// qaMediaAnime builds one upstream anime payload (the v1 shape Convert
// decodes; score is a decimal STRING upstream; genres ride russian-first).
func qaMediaAnime(id int, name, russian, kind string, episodes int, aired, score string) map[string]any {
	return map[string]any{
		"id": id, "name": name, "russian": russian, "kind": kind, "status": "released",
		"score": score, "episodes": episodes, "aired_on": aired,
		"description": qaMediaDesc,
		"url":         qaSerialUpstreamSearch + "/" + strconv.Itoa(id) + "-qa",
		"image":       map[string]any{"original": "/images/animes/" + strconv.Itoa(id) + ".jpg"},
		"genre": []any{
			map[string]any{"name": "Adventure", "russian": "Приключения"},
			map[string]any{"name": "Drama", "russian": "Драма"},
		},
	}
}

// qaMediaRoles is the stub's GET /api/animes/{id}/roles payload (the v1 shape
// castField decodes — "seyu" is the upstream's own spelling): character one
// carries a russian name + a seiyuu credit + a portrait; character two has no
// credit — the served entry must stay honest-partial ({name, photo_url}).
var qaMediaRoles = []any{
	map[string]any{
		"name": "Hero", "russian": "Герой",
		"image": map[string]any{"original": "/images/characters/hero.jpg"},
		"seyu":  []any{map[string]any{"name": "VA One", "russian": "Ва Один"}},
	},
	map[string]any{
		"name": "Side", "russian": "Друг",
		"image": map[string]any{"original": "/images/characters/side.jpg"},
		"seyu":  []any{},
	},
}

// qaMediaUpstream is the fake shikimori origin: the search endpoint serves
// the per-title candidate lists (right anime first, movie decoy second), the
// by-id endpoint the single-object shape, the roles endpoint the cast
// source. Every request is recorded.
type qaMediaUpstream struct {
	baseURL string
	srv     *httptest.Server
	mu      sync.Mutex
	seen    []qaSerialUpstreamReq
}

// qaMediaStartUpstream boots the stub.
func qaMediaStartUpstream(t *testing.T) *qaMediaUpstream {
	t.Helper()
	s := &qaMediaUpstream{}
	mux := http.NewServeMux()
	mux.HandleFunc(qaSerialUpstreamSearch, func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		list := map[string][]map[string]any{
			qaMediaTitle: {
				qaMediaAnime(qaMediaID, qaMediaTitle, qaMediaRussian, "tv", 12, qaMediaAired, "7.7"),
				qaMediaAnime(qaMediaDecoyID, qaMediaTitle+" Movie", qaMediaRussian+" фильм", "movie", 1, "2021-08-06", "6.1"),
			},
		}[r.URL.Query().Get("search")]
		if list == nil {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, list)
	})
	mux.HandleFunc(qaSerialUpstreamSearch+"/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		rest := strings.TrimPrefix(r.URL.Path, qaSerialUpstreamSearch+"/")
		if id := strings.TrimSuffix(rest, "/roles"); id != rest {
			if id != strconv.Itoa(qaMediaID) {
				http.NotFound(w, r)
				return
			}
			qaSerialWriteJSON(t, w, qaMediaRoles)
			return
		}
		e, ok := map[string]map[string]any{
			strconv.Itoa(qaMediaID): qaMediaAnime(qaMediaID, qaMediaTitle, qaMediaRussian, "tv", 12, qaMediaAired, "7.7"),
		}[rest]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, e)
	})
	s.srv = httptest.NewServer(mux)
	t.Cleanup(s.srv.Close)
	s.baseURL = s.srv.URL
	return s
}

func (s *qaMediaUpstream) record(r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seen = append(s.seen, qaSerialUpstreamReq{
		method: r.Method, path: r.URL.Path, query: r.URL.RawQuery, ua: r.Header.Get("User-Agent"),
	})
}

// requests snapshots the recorded upstream traffic.
func (s *qaMediaUpstream) requests() []qaSerialUpstreamReq {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]qaSerialUpstreamReq(nil), s.seen...)
}

