// qaMediaJoint is one composed media-data joint: the real server subprocess,
// the stub upstream, and the store seam over the server's own db.
type qaMediaJoint struct {
	srv    qaSerialServer
	client *http.Client
	token  string
	up     *qaMediaUpstream
	st     *store.Store
	lib    int64
}

// qaMediaStartJoint boots the joint: the seven server-side binaries, the
// REAL cmd/mellifera subprocess (whose main.go wiring carries the production
// ModulePresentation closure — the AddChainSource walk the projection
// consumes — plus the real queue and the scan notify), and the serial
// library over root. The scan stays with the caller.
func qaMediaStartJoint(t *testing.T, up *qaMediaUpstream, root string) *qaMediaJoint {
	t.Helper()
	tmp := t.TempDir()
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-media-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-media-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-media-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-media-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-media-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-media-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-media-grabber", "./plugins/frame-grabber"),
	}, up.baseURL, tmp, "qa-media-admin-token")
	// The store seam: the test process opens the server's OWN database (the
	// DSN main.go computes from MELLIFERA_DATA_DIR) and writes the fixture
	// documents through the real store code path. Open is idempotent (every
	// migration is CREATE ... IF NOT EXISTS) and WAL + busy_timeout make the
	// sequential second writer safe.
	st, err := store.Open(context.Background(), filepath.Join(srv.dataDir, "mellifera.db"))
	if err != nil {
		t.Fatalf("open the server's store seam: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	j := &qaMediaJoint{
		srv:    srv,
		client: &http.Client{Timeout: httpTimeout},
		token:  "qa-media-admin-token",
		up:     up,
		st:     st,
	}
	j.lib = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, j.token, root, "QA Media Data")
	return j
}

// qaMediaSeriesList decodes a library's series LIST rows (metadata included).
func (j *qaMediaJoint) seriesList(t *testing.T) []qaMediaSeries {
	t.Helper()
	var resp qaMediaSeriesList
	url := j.srv.baseURL + "/api/v1/series?library=" + strconv.FormatInt(j.lib, 10)
	if status := doRequest(t, j.client, http.MethodGet, url, j.token, nil, &resp); status != http.StatusOK {
		t.Fatalf("list series lib %d: HTTP %d, want 200", j.lib, status)
	}
	return resp.Items
}

// qaMediaSeriesByPath returns the library's series row at rel (fatal when
// missing).
func (j *qaMediaJoint) seriesByPath(t *testing.T, rel string) qaMediaSeries {
	t.Helper()
	for _, sr := range j.seriesList(t) {
		if sr.RelativePath == rel {
			return sr
		}
	}
	t.Fatalf("series %q missing from library %d", rel, j.lib)
	return qaMediaSeries{}
}

