// qaMediaRefresh kicks the REAL whole-library shikimori sweep (202 + counts).
func (j *qaMediaJoint) refresh(t *testing.T) (queued, stripped int) {
	t.Helper()
	var res struct {
		Queued   int `json:"queued"`
		Stripped int `json:"stripped"`
		Deferred int `json:"deferred"`
	}
	url := j.srv.baseURL + "/api/v1/libraries/" + strconv.FormatInt(j.lib, 10) + "/refresh"
	body := map[string]any{"plugin_id": qaMediaPlugin}
	if status := doRequest(t, j.client, http.MethodPost, url, j.token, body, &res); status != http.StatusAccepted {
		t.Fatalf("POST refresh: HTTP %d, want 202", status)
	}
	return res.Queued, res.Stripped
}

// qaMediaAwaitEnrichedSeries polls until the row at rel settles ready with
// BOTH the serial-parser and shikimori namespaces landed, returning the row.
// The failure dump carries the raw document (its _stages carry a skipped
// stage's reason — the diagnosis surface).
func (j *qaMediaJoint) awaitEnrichedSeries(t *testing.T, rel string) qaMediaSeries {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		for _, sr := range j.seriesList(t) {
			if sr.RelativePath != rel || sr.Status != "ready" {
				continue
			}
			doc := parseAsyncDoc(t, sr.Document)
			if doc.Sources["serial-parser"] != nil && doc.Sources[qaMediaPlugin] != nil {
				return sr
			}
		}
		time.Sleep(probeInterval)
	}
	sr := j.seriesByPath(t, rel)
	t.Fatalf("series %q: shikimori namespace never landed (status %s); doc:\n%s", rel, sr.Status, sr.Document)
	return qaMediaSeries{}
}

// qaMediaNamespace fetches the stored sources.shikimori namespace off the
// series detail row (fatal when absent).
func (j *qaMediaJoint) storedNamespace(t *testing.T, seriesID string) (ns map[string]any, doc asyncDoc, raw json.RawMessage) {
	t.Helper()
	sr := j.seriesDetail(t, seriesID)
	doc = parseAsyncDoc(t, sr.Document)
	ns, ok := doc.Sources[qaMediaPlugin]
	if !ok {
		t.Fatalf("series %s: sources.%s missing; doc:\n%s", seriesID, qaMediaPlugin, sr.Document)
	}
	return ns, doc, sr.Document
}

// qaMediaAssertStoredSynopsis pins the stored namespace's convention synopsis
// fields — the SELECTED candidate's values verbatim (never the movie decoy's).
func qaMediaAssertStoredSynopsis(t *testing.T, ns map[string]any) {
	t.Helper()
	title, _ := ns["title"].(map[string]any)
	if asyncStr(title, "romaji") != qaMediaTitle || asyncStr(title, "russian") != qaMediaRussian {
		t.Errorf("sources.shikimori.title = %v, want {romaji:%s russian:%s} (RU-first, the tv candidate)", title, qaMediaTitle, qaMediaRussian)
	}
	if asyncStr(ns, "kind") != "tv" || asyncStr(ns, "status") != "released" {
		t.Errorf("sources.shikimori kind/status = %q/%q, want tv/released (never the movie decoy)",
			asyncStr(ns, "kind"), asyncStr(ns, "status"))
	}
	if n, _ := ns["episodes"].(float64); int(n) != 12 {
		t.Errorf("sources.shikimori.episodes = %v, want 12", ns["episodes"])
	}
	if asyncStr(ns, "aired_on") != qaMediaAired {
		t.Errorf("sources.shikimori.aired_on = %q, want %q", asyncStr(ns, "aired_on"), qaMediaAired)
	}
	if s, _ := ns["score"].(float64); s != qaMediaScore {
		t.Errorf("sources.shikimori.score = %v, want %v (upstream string decoded to a number)", ns["score"], qaMediaScore)
	}
	if asyncStr(ns, "description") != qaMediaDesc {
		t.Errorf("sources.shikimori.description = %q, want %q (the synopsis carrier)", asyncStr(ns, "description"), qaMediaDesc)
	}
	genres, _ := ns["genres"].([]any)
	wantGenres := []string{"Приключения", "Драма"}
	if len(genres) != len(wantGenres) {
		t.Errorf("sources.shikimori.genres = %v, want %v", genres, wantGenres)
	} else {
		for i, g := range genres {
			if got, _ := g.(string); got != wantGenres[i] {
				t.Errorf("sources.shikimori.genres[%d] = %q, want %q", i, got, wantGenres[i])
			}
		}
	}
}

// qaMediaWantCast is the cast the conformer must compose from qaMediaRoles:
// russian-preferred character names, the free-text seiyuu credit only when
// present, the portrait made ABSOLUTE against the stub origin (the plugin
// resolves apiBase from MELLIFERA_SHIKIMORI_UPSTREAM at process start).
func qaMediaWantCast(stubOrigin string) []map[string]any {
	return []map[string]any{
		{"name": "Герой", "role": "Ва Один", "photo_url": stubOrigin + "/images/characters/hero.jpg"},
		{"name": "Друг", "photo_url": stubOrigin + "/images/characters/side.jpg"},
	}
}

// qaMediaAssertCast pins one cast array (stored namespace or served block)
// entry-for-entry: the exact member set per entry — role only when the
// character carries a credit (honest partial, never an empty string).
func qaMediaAssertCast(t *testing.T, where string, cast []any, want []map[string]any) {
	t.Helper()
	if len(cast) != len(want) {
		t.Fatalf("%s cast = %v, want %d entries", where, cast, len(want))
	}
	for i, entry := range cast {
		m, ok := entry.(map[string]any)
		if !ok {
			t.Fatalf("%s cast[%d] = %v, want an object", where, i, entry)
		}
		if asyncStr(m, "name") != want[i]["name"] {
			t.Errorf("%s cast[%d].name = %q, want %q (russian preferred)", where, i, asyncStr(m, "name"), want[i]["name"])
		}
		role, hasRole := m["role"]
		if wantRole, wantIt := want[i]["role"]; wantIt {
			if !hasRole || role != wantRole {
				t.Errorf("%s cast[%d].role = %v, want %q", where, i, role, wantRole)
			}
		} else if hasRole {
			t.Errorf("%s cast[%d] carries role %q, want none (no credit → no member)", where, i, role)
		}
		if got := asyncStr(m, "photo_url"); got != want[i]["photo_url"] {
			t.Errorf("%s cast[%d].photo_url = %q, want the absolute stub url %q", where, i, got, want[i]["photo_url"])
		}
	}
}

// qaMediaAssertAbout pins the served about block: source naming shikimori and
// every synopsis member verbatim from the winning namespace.
func qaMediaAssertAbout(t *testing.T, where string, md map[string]any) {
	t.Helper()
	about, ok := md["about"].(map[string]any)
	if !ok {
		t.Fatalf("%s metadata.about = %v, want an object naming its source", where, md["about"])
	}
	if asyncStr(about, "source") != qaMediaPlugin {
		t.Errorf("%s metadata.about.source = %q, want %q", where, asyncStr(about, "source"), qaMediaPlugin)
	}
	if asyncStr(about, "description") != qaMediaDesc {
		t.Errorf("%s metadata.about.description = %q, want %q", where, asyncStr(about, "description"), qaMediaDesc)
	}
	if s, _ := about["score"].(float64); s != qaMediaScore {
		t.Errorf("%s metadata.about.score = %v, want %v", where, about["score"], qaMediaScore)
	}
	if asyncStr(about, "kind") != "tv" || asyncStr(about, "status") != "released" {
		t.Errorf("%s metadata.about kind/status = %q/%q, want tv/released", where, asyncStr(about, "kind"), asyncStr(about, "status"))
	}
	if n, _ := about["episodes"].(float64); int(n) != 12 {
		t.Errorf("%s metadata.about.episodes = %v, want 12", where, about["episodes"])
	}
	if asyncStr(about, "aired_on") != qaMediaAired {
		t.Errorf("%s metadata.about.aired_on = %q, want %q", where, asyncStr(about, "aired_on"), qaMediaAired)
	}
	genres, _ := about["genres"].([]any)
	if len(genres) != 2 || asyncStrFirst(genres) != "Приключения" {
		t.Errorf("%s metadata.about.genres = %v, want the RU-first pair [Приключения Драма]", where, genres)
	}
}

// asyncStrFirst reads the first element of a decoded string array ("" when
// the shape is off).
func asyncStrFirst(arr []any) string {
	if len(arr) == 0 {
		return ""
	}
	s, _ := arr[0].(string)
	return s
}

// TestQAMediaDataJoint is the Tier-1 acceptance floor (spec scenario
// fb9511dbf7bcf5e2): a series enriches through the conforming source against
// a stub upstream and the stored document, plus episode and no-carrier
// fixture documents, are served through the element surfaces with the
// convention blocks resolved first-chain-wins.
func TestQAMediaDataJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA media-data joint: skips under -short (builds binaries + subprocesses)")
	}
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("QA media-data joint needs %s on PATH (fixture generation + probing; INV4: optional binary): %v", bin, err)
		}
	}

	root := t.TempDir()
	qaMediaWriteFixtures(t, root)
	up := qaMediaStartUpstream(t)
	j := qaMediaStartJoint(t, up, root)

	// --- enriched_search_leg: one scan, one search leg, the namespace lands ---
	res := scanLibrary(t, j.client, j.srv.baseURL, j.token, j.lib)
	if res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("media library: scan discovered=%d persisted=%d, want 3/3 (1 serial record + 2 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	sr := j.awaitEnrichedSeries(t, qaMediaDir)

	// STORED, search leg: the convention synopsis fields verbatim; cast
	// ABSENT — the roles fetch is anchored-only, so the search-run namespace
	// cannot carry it (the boundary the next leg must cross).
	ns, _, rawDoc := j.storedNamespace(t, sr.ID)
	qaMediaAssertStoredSynopsis(t, ns)
	if _, hasCast := ns["cast"]; hasCast {
		t.Fatalf("search-leg sources.shikimori carries cast %v, want none (the roles fetch is anchored-only)", ns["cast"])
	}
	var rawWhole map[string]any
	if err := json.Unmarshal(rawDoc, &rawWhole); err != nil {
		t.Fatalf("decode stored doc: %v", err)
	}
	wholeIDs, _ := rawWhole["identifiers"].(map[string]any)
	if got, _ := wholeIDs["shikimori_id"].(float64); int(got) != qaMediaID {
		t.Fatalf("identifiers.shikimori_id = %v, want %d (the anchor the anchored leg needs)", wholeIDs["shikimori_id"], qaMediaID)
	}
	if reqs := up.requests(); len(reqs) != 1 {
		t.Fatalf("upstream saw %d requests after the search leg, want exactly 1: %+v", len(reqs), reqs)
	}

	// --- anchored_leg_writes_cast: the REAL refresh sweep re-derives ANCHORED ---
	queued, stripped := j.refresh(t)
	if queued != 1 || stripped != 1 {
		t.Fatalf("refresh = queued %d stripped %d, want 1/1 (the one series row carries the namespace)", queued, stripped)
	}
	sr = j.awaitEnrichedSeries(t, qaMediaDir) // the FRESH (anchored) namespace
	ns, _, _ = j.storedNamespace(t, sr.ID)
	qaMediaAssertStoredSynopsis(t, ns) // the synopsis members survive the sweep verbatim
	storedCast, ok := ns["cast"].([]any)
	if !ok {
		t.Fatalf("anchored sources.shikimori cast = %v, want the composed array (the roles body landed)", ns["cast"])
	}
	qaMediaAssertCast(t, "stored", storedCast, qaMediaWantCast(up.baseURL))
	// episode-titles (shikimori-enrichment delta) sanctions the /episodes
	// companion: the anchored plan now carries by-id + roles + episodes.
	tail := up.requests()
	if len(tail) != 4 {
		t.Fatalf("upstream saw %d requests total, want 4 (search + by-id + roles + episodes): %+v", len(tail), tail)
	}
	paths := map[string]bool{
		qaSerialUpstreamSearch + "/" + strconv.Itoa(qaMediaID):               false,
		qaSerialUpstreamSearch + "/" + strconv.Itoa(qaMediaID) + "/roles":    false,
		qaSerialUpstreamSearch + "/" + strconv.Itoa(qaMediaID) + "/episodes": false,
	}
	for _, r := range tail[1:] {
		if r.method != http.MethodGet {
			t.Errorf("anchored request %s %s, want GET", r.method, r.path)
		}
		if _, hit := paths[r.path]; hit {
			paths[r.path] = true
		} else {
			t.Errorf("anchored request hit %s, want one of the by-id/roles/episodes endpoints %v", r.path, paths)
		}
	}
	for path, hit := range paths {
		if !hit {
			t.Errorf("no anchored fetch for %s (the anchor must drive the by-id + roles + episodes plan)", path)
		}
	}

	// --- served_series_blocks: the projection over the REAL chain ---
	t.Run("served_series_blocks", func(t *testing.T) {
		detail := j.seriesDetail(t, sr.ID)
		if detail.Metadata == nil {
			t.Fatalf("served series detail carries NO metadata block, want about + cast (doc:\n%s)", detail.Document)
		}
		qaMediaAssertAbout(t, "series detail", detail.Metadata)
		servedCast, ok := detail.Metadata["cast"].([]any)
		if !ok {
			t.Fatalf("served series detail metadata.cast = %v, want the stored array verbatim", detail.Metadata["cast"])
		}
		qaMediaAssertCast(t, "series detail", servedCast, qaMediaWantCast(up.baseURL))
		if _, hasEpisode := detail.Metadata["episode"]; hasEpisode {
			t.Errorf("served series detail carries an episode block %v, want none (the episode group is episode-document-only)", detail.Metadata["episode"])
		}
		// The list surface shares the seam — the same blocks on the list row.
		listRow := j.seriesByPath(t, qaMediaDir)
		if len(listRow.Metadata) != len(detail.Metadata) {
			t.Errorf("served series list metadata = %v, want the detail blocks %v", listRow.Metadata, detail.Metadata)
		}
		qaMediaAssertAbout(t, "series list", listRow.Metadata)
		// The production closure's chain rides the library module block: the
		// serial config order, every gate-resolved verdict enabled.
		lib := j.library(t)
		if lib.Module == nil {
			t.Fatalf("library %d serves no module block, want the source_chain", j.lib)
		}
		wantChain := []qaMediaChainBinding{
			{ID: "serial-parser", Enabled: true},
			{ID: "frame-grabber", Enabled: true},
			{ID: qaMediaPlugin, Enabled: true},
		}
		if len(lib.Module.SourceChain) != len(wantChain) {
			t.Fatalf("served source_chain = %v, want %v", lib.Module.SourceChain, wantChain)
		}
		for i, b := range lib.Module.SourceChain {
			if b != wantChain[i] {
				t.Errorf("served source_chain[%d] = %+v, want %+v (the config chain order, gate-resolved)", i, b, wantChain[i])
			}
		}
	})

	// --- the fixture documents ride in through the REAL store seam ---
	schema := sr.SchemaVersion
	ctx := context.Background()

	t.Run("episode_fixture_serves_episode_block", func(t *testing.T) {
		host := j.itemByPath(t, qaMediaEp2Rel)
		row, err := j.st.GetItem(ctx, host.ID)
		if err != nil {
			t.Fatalf("get item %s via the store seam: %v", host.ID, err)
		}
		// The episode fixture (media-data-convention D2): the parsed anchor
		// gates the episode group; season/episode ride the parser namespace;
		// the episode's OWN title/description sit in sources.shikimori.
		row.Document = qaMediaEncodeDoc(t, map[string]any{
			"parsed": map[string]any{"series_relative_path": qaMediaDir},
			"sources": map[string]any{
				"serial-parser": map[string]any{"season": 1, "episode": 2},
				"frame-grabber": map[string]any{"thumbnail_path": "/streams/qa-media-e02.jpg"},
				qaMediaPlugin: map[string]any{
					"title":       "Эпизод: отель",
					"description": "описание эпизода: отель",
				},
			},
		})
		if err := j.st.PutItem(ctx, row); err != nil {
			t.Fatalf("put episode fixture: %v", err)
		}
		served := j.itemDetail(t, host.ID)
		if served.Metadata == nil {
			t.Fatalf("served episode fixture carries NO metadata block, want exactly the episode block")
		}
		ep, ok := served.Metadata["episode"].(map[string]any)
		if !ok {
			t.Fatalf("served episode fixture metadata = %v, want the episode block", served.Metadata)
		}
		if asyncStr(ep, "title") != "Эпизод: отель" || asyncStr(ep, "description") != "описание эпизода: отель" {
			t.Errorf("served metadata.episode = %v, want {title description} verbatim", ep)
		}
		if len(ep) != 2 {
			t.Errorf("served metadata.episode carries %d members %v, want exactly {title, description}", len(ep), ep)
		}
		if _, leak := served.Metadata["about"]; leak {
			t.Errorf("served episode fixture carries an about block (the episode's description is NEVER the show's about)")
		}
		if _, leak := served.Metadata["cast"]; leak {
			t.Errorf("served episode fixture carries a cast block %v, want none", served.Metadata["cast"])
		}
	})

	t.Run("item_carries_about_and_cast", func(t *testing.T) {
		// A NON-episode fixture item (no parsed anchor → the series-document
		// groups apply) carrying the shikimori carriers: the served item
		// surface resolves about + cast naming shikimori.
		fixture := store.Item{
			ID:            "itm_qamediafeature",
			ModuleID:      "serial",
			LibraryID:     j.lib,
			FileID:        "qa-media-feature.mkv",
			RelativePath:  "qa-media-fixture/QA Feature Cut.mkv",
			MediaType:     "video",
			SchemaVersion: schema,
			Status:        "ready",
			Document: qaMediaEncodeDoc(t, map[string]any{
				"parsed": map[string]any{"title": "QA Feature Cut"},
				"sources": map[string]any{
					"serial-parser": map[string]any{"title": "QA Feature Cut"},
					"frame-grabber": map[string]any{"thumbnail_path": "/streams/qa-media-feature.jpg"},
					qaMediaPlugin: map[string]any{
						"description": qaMediaDesc,
						"genres":      []any{"Приключения", "Драма"},
						"score":       qaMediaScore,
						"kind":        "tv",
						"status":      "released",
						"episodes":    12,
						"aired_on":    qaMediaAired,
						"cast":        qaMediaWantCast(up.baseURL),
					},
				},
			}),
		}
		if err := j.st.PutItem(ctx, fixture); err != nil {
			t.Fatalf("put about+cast fixture: %v", err)
		}
		served := j.itemDetail(t, fixture.ID)
		if served.Metadata == nil {
			t.Fatalf("served about+cast item carries NO metadata block, want about + cast")
		}
		qaMediaAssertAbout(t, "item detail", served.Metadata)
		servedCast, ok := served.Metadata["cast"].([]any)
		if !ok {
			t.Fatalf("served item metadata.cast = %v, want the stored array verbatim", served.Metadata["cast"])
		}
		qaMediaAssertCast(t, "item detail", servedCast, qaMediaWantCast(up.baseURL))
		if _, hasEpisode := served.Metadata["episode"]; hasEpisode {
			t.Errorf("served about+cast item carries an episode block, want none (no episode fields stored)")
		}
	})

	t.Run("no_carrier_serves_nothing", func(t *testing.T) {
		// Every namespace present, NO convention carrier anywhere: facts
		// alone (genres/score/kind/status/episodes/aired_on, a parser title)
		// never claim a group (D8) — the wire omits the metadata key
		// entirely, so the decoded map is nil.
		if err := j.st.PutSeries(ctx, store.Series{
			ModuleID:      "serial",
			LibraryID:     j.lib,
			RelativePath:  "QA No Carrier S01",
			SchemaVersion: schema,
			Status:        "ready",
			Document: qaMediaEncodeDoc(t, map[string]any{
				"parsed": map[string]any{"serial_record": true, "dir_name_raw": "QA No Carrier S01"},
				"sources": map[string]any{
					"serial-parser": map[string]any{"title": "QA No Carrier", "season": 1, "dir_name_raw": "QA No Carrier S01"},
					"frame-grabber": map[string]any{"thumbnail_path": "/streams/qa-media-nc.jpg"},
					qaMediaPlugin: map[string]any{
						"genres": []any{"Драма"}, "score": 8.1, "kind": "tv",
						"status": "released", "episodes": 24, "aired_on": "2020-01-01",
					},
				},
			}),
		}); err != nil {
			t.Fatalf("put no-carrier fixture: %v", err)
		}
		for _, sr := range j.seriesList(t) {
			if sr.RelativePath != "QA No Carrier S01" {
				continue
			}
			if sr.Metadata != nil {
				t.Errorf("no-carrier series list metadata = %v, want NONE on the wire (honest absence)", sr.Metadata)
			}
			detail := j.seriesDetail(t, sr.ID)
			if detail.Metadata != nil {
				t.Errorf("no-carrier series detail metadata = %v, want NONE on the wire (honest absence)", detail.Metadata)
			}
		}
		// The untouched REAL episode item — a pipeline-produced document with
		// no episode-title writer yet — serves nothing either.
		e1 := j.itemByPath(t, qaMediaEp1Rel)
		if e1.Metadata != nil {
			t.Errorf("real episode item %s metadata = %v, want NONE (no writer emits episode title/description yet)", e1.ID, e1.Metadata)
		}
	})
}

// qaMediaEncodeDoc marshals one fixture document (test-local helper so the
// PutItem/PutSeries call sites stay on one line each).
func qaMediaEncodeDoc(t *testing.T, doc map[string]any) json.RawMessage {
	t.Helper()
	raw, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("encode fixture doc: %v", err)
	}
	return raw
}
